// line yaccpar:1

// parser for yacc output
//
// The parser stops at the first syntax error, so there is no error recovery.

interface YYLexer {
mut:
	lex(mut lval YYSymType) int
	error(s string) IError
}

interface YYParser {
mut:
	parse(mut YYLexer) !int
}

// The stack is kept by the caller between statements, so that it is not made again
// for each one (a YYSymType is big).
struct YYParserImpl {
mut:
	lval  YYSymType
	stack []YYSymType
	char  int
}

fn yy_new_parser() YYParser {
	return YYParserImpl{}
}

const yy_flag = -1000

// yy_tokname is only given tokens from the lexer and the tables, so they all
// have a name.
fn yy_tokname(c int) string {
	return yy_toknames[c - 1]
}

const tokstart = 4

fn yy_error_message(state int, look_ahead int) string {
	mut res := 'syntax error: unexpected ' + yy_tokname(look_ahead)

	// To match Bison, suggest at most four expected tokens.
	mut expected := []int{cap: 4}

	// Look for shiftable tokens.
	base := int(yy_pact[state])
	for tok := tokstart; tok - 1 < yy_toknames.len; tok++ {
		n := base + tok
		if n >= 0 && n < yy_last && int(yy_chk[int(yy_act[n])]) == tok {
			if expected.len == expected.cap {
				return res
			}
			expected << tok
		}
	}

	for i, tok in expected {
		if i == 0 {
			res += ', expecting '
		} else {
			res += ' or '
		}
		res += yy_tokname(tok)
	}
	return res
}

// The tables are only indexed with the states and tokens they were built for,
// so they do not need bounds checks.
@[direct_array_access]
fn yylex1(mut lex YYLexer, mut lval YYSymType) (int, int) {
	ch := lex.lex(mut lval)
	if ch <= 0 {
		return ch, int(yy_tok1[0])
	}
	return ch, int(yy_tok2[ch - yy_private])
}

@[direct_array_access]
