	mut yyp := -1
	unsafe {
		goto yystack
	}

	ret0:
	return 0

	yystack:
	// put a state and value onto the stack. There is always one more slot so
	// that $1 of an ε production is in range after a reduction.
	yyp++
	if yyp + 1 >= yy_s.len {
		mut nyys := []YYSymType{len: yy_s.len * 2}
		gocopy(mut nyys, yy_s)
		yy_s = nyys.clone()
